--
-- Table structure for table `t_finance_fee`
--

DROP TABLE IF EXISTS `t_finance_fee`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_finance_fee` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `student_id` varchar(36) NOT NULL COMMENT '学生ID',
  `student_no` varchar(32) NOT NULL COMMENT '学号 S20260001',
  `student_name` varchar(50) NOT NULL COMMENT '学生姓名',
  `class_id` varchar(36) DEFAULT NULL COMMENT '班级ID',
  `class_name` varchar(50) DEFAULT NULL COMMENT '班级名称',
  `dept_code` int DEFAULT NULL COMMENT '部门 1初高部 2大学部',
  `head_teacher_id` varchar(36) DEFAULT NULL COMMENT '班主任ID',
  `head_teacher_name` varchar(50) DEFAULT NULL COMMENT '班主任姓名',
  `fee_type` int NOT NULL COMMENT '缴费类型 1学费2住宿费3餐费4保险费5试学费',
  `amount` int NOT NULL COMMENT '金额（单位：分）',
  `pay_status` int NOT NULL DEFAULT '1' COMMENT '缴费状态 1待缴2已缴3已核对4逾期5冻结',
  `pay_date` date DEFAULT NULL COMMENT '缴费日期',
  `expire_date` date DEFAULT NULL COMMENT '到期日期（临期名单查询用）',
  `period` varchar(32) DEFAULT NULL COMMENT '费用周期 如 2026-09',
  `voucher_url` varchar(255) DEFAULT NULL COMMENT '缴费凭证URL',
  `voucher_no` varchar(64) DEFAULT NULL COMMENT '凭证编号',
  `voucher_by` varchar(36) DEFAULT NULL COMMENT '上传凭证人ID',
  `voucher_time` datetime DEFAULT NULL COMMENT '上传凭证时间',
  `is_verified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '财务是否已核对',
  `verified_by` varchar(36) DEFAULT NULL COMMENT '核对人ID',
  `verified_by_name` varchar(50) DEFAULT NULL COMMENT '核对人姓名',
  `verified_time` datetime DEFAULT NULL COMMENT '核对时间',
  `is_rejected` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否被打回',
  `reject_reason` varchar(255) DEFAULT NULL COMMENT '打回原因',
  `is_in_bill` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已归集账单明细',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `source_module` int DEFAULT NULL COMMENT '来源模块 1咨询模块 2教务模块 3财务自建',
  PRIMARY KEY (`id`),
  KEY `idx_fee_student_id` (`student_id`),
  KEY `idx_fee_student_no` (`student_no`),
  KEY `idx_fee_class_fee` (`class_id`,`fee_type`),
  KEY `idx_fee_expire_date` (`expire_date`),
  KEY `idx_fee_pay_status` (`pay_status`),
  KEY `idx_fee_is_deleted` (`is_deleted`),
  KEY `idx_fee_source_module` (`source_module`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='缴费记录表';
