DROP TABLE IF EXISTS `t_finance_fee_standard`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_finance_fee_standard` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `fee_type` int NOT NULL COMMENT '费用类型 1学费2住宿费3餐费4保险费5试学费',
  `dept_code` int NOT NULL COMMENT '适用部门 1初高部 2大学部',
  `amount` int NOT NULL COMMENT '标准金额（单位：分）',
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用；停用后上游取数接口会拒绝',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注，如调价说明',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_standard_type_dept` (`fee_type`,`dept_code`,`is_deleted`),
  KEY `idx_standard_enabled` (`is_enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

