--

DROP TABLE IF EXISTS `t_finance_freeze`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_finance_freeze` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `student_id` varchar(36) NOT NULL COMMENT '学生ID',
  `student_no` varchar(32) NOT NULL COMMENT '学号',
  `student_name` varchar(50) NOT NULL COMMENT '学生姓名',
  `class_id` varchar(36) DEFAULT NULL COMMENT '班级ID',
  `class_name` varchar(50) DEFAULT NULL COMMENT '班级名称',
  `dept_code` int DEFAULT NULL COMMENT '部门 1初高部 2大学部',
  `student_status` int NOT NULL COMMENT '冻结时的学生状态 6休学（见数据字典4.1）',
  `freeze_scope` varchar(64) NOT NULL DEFAULT '餐费、住宿费' COMMENT '冻结范围',
