  `refund_amount` int NOT NULL COMMENT '退费金额（单位：分）',
  `refund_reason` varchar(255) NOT NULL COMMENT '退费原因（必填）',
  `refund_status` int NOT NULL DEFAULT '1' COMMENT '退费状态 1待提交2待经理审批3待教务核算4待财务出款5待校长审批6已退费7已驳回',
