  `manager_approve_by` varchar(36) DEFAULT NULL COMMENT '经理审批人ID',
  `academic_check_time` datetime DEFAULT NULL COMMENT '教务核算时间',
  `academic_check_by` varchar(36) DEFAULT NULL COMMENT '教务核算人ID',
  `principal_approve_time` datetime DEFAULT NULL COMMENT '校长审批时间',
  `principal_approve_by` varchar(36) DEFAULT NULL COMMENT '校长审批人ID',
  `pushed_time` datetime DEFAULT NULL COMMENT '推送给财务的时间',
  `finance_pay_time` datetime DEFAULT NULL COMMENT '财务出款时间',
  `finance_pay_by` varchar(36) DEFAULT NULL COMMENT '财务出款人ID',
  `reject_reason` varchar(255) DEFAULT NULL COMMENT '驳回原因',
  `is_in_bill` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已归集账单明细',
